"""Octree diagrams for the paper (vector PDFs in figures/), regenerated by `make.py diagrams`.

    f  diag-tree.pdf      a disc as a uniform grid and as a cross-section through the octree with the same finest cell
                          (interior merged, cut cells at the finest level), and a sphere's octree
                          in 3-D, lower half
    g  diag-storage.pdf   cells stored against cells across a sphere, N: the uniform grid, the
                          octree's leaves and the cut cells, counted (not modelled); data in
                          data/storage.json
    h  diag-read-cut.pdf  the read's cut through the tree for one tower: clipped pieces nearest
                          the arm, cut-cell moments next, coarse nodes beyond; with each layer's
                          error (the layered read)

Same style as diagrams.py (Okabe–Ito, hatching as a second cue).

    python scripts/octree_diagrams.py
"""

from __future__ import annotations

import json
import math
import pathlib
import sys

import matplotlib.pyplot as plt
import numpy as np
from matplotlib.patches import Circle, Rectangle

HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
sys.path.insert(0, str(HERE.parents[2] / "research" / "exact-skin-and-partial-fill"))
import diagrams as dg  # noqa: E402
import lighting as lit  # noqa: E402

FIG = HERE.parent / "figures"
DATA = HERE.parent / "data"
SOLID, CUT = dg.SKY, dg.ORANGE


# ------------------------------------------------------------------ classification

def state2(x0: float, y0: float, s: float, c=(0.07, -0.05), r: float = 1.0) -> str:
    far = max(math.hypot(x - c[0], y - c[1]) for x in (x0, x0 + s) for y in (y0, y0 + s))
    nx, ny = min(max(c[0], x0), x0 + s), min(max(c[1], y0), y0 + s)
    near = math.hypot(nx - c[0], ny - c[1])
    return "in" if far <= r else "out" if near >= r else "cut"


def state3(o: np.ndarray, s: float, c: np.ndarray, r: float) -> str:
    corners = o + s * np.array([[i, j, k] for i in (0, 1) for j in (0, 1) for k in (0, 1)])
    far = np.max(np.linalg.norm(corners - c, axis=1))
    near = np.linalg.norm(np.clip(c, o, o + s) - c)
    return "in" if far <= r else "out" if near >= r else "cut"


def section_tree(x0, y0, s, depth, max_depth, out, st=state2):
    k = st(x0, y0, s)
    if k == "out":
        return
    if k == "in" or depth == max_depth:
        out.append((x0, y0, s, k))
        return
    for dx in (0, s / 2):
        for dy in (0, s / 2):
            section_tree(x0 + dx, y0 + dy, s / 2, depth + 1, max_depth, out, st)


def octree_counts(depth: int) -> tuple[int, int, int, list]:
    """A sphere of radius 0.39 of the root cube (off-centre), to `depth`: (uniform cells that are
    in or cut, tree leaves, cut cells, leaves)."""
    c = np.array([0.503, 0.497, 0.501])
    r = 0.39
    leaves: list = []

    def rec(o: np.ndarray, s: float, d: int) -> None:
        k = state3(o, s, c, r)
        if k == "out":
            return
        if k == "in" or d == depth:
            leaves.append((o, s, k))
            return
        for i in (0, 1):
            for j in (0, 1):
                for kk in (0, 1):
                    rec(o + np.array([i, j, kk]) * s / 2, s / 2, d + 1)

    rec(np.zeros(3), 1.0, 0)
    n = 2 ** depth
    h = 1.0 / n
    uniform = sum(int(round((s / h) ** 3)) for o, s, k in leaves)
    cut = sum(1 for o, s, k in leaves if k == "cut")
    return uniform, len(leaves), cut, leaves


# ------------------------------------------------------------------ f

def fig_tree() -> None:
    fig = plt.figure(figsize=(6.8, 2.6))
    d = 5
    side = 2.56
    n = 2 ** d
    s = side / n
    leaves: list = []
    section_tree(-side / 2, -side / 2, side, 0, d, leaves)
    ax = fig.add_subplot(1, 3, 1)
    dg.bare(ax)
    count = 0
    for i in range(n):
        for j in range(n):
            k = state2(-side / 2 + i * s, -side / 2 + j * s, s)
            if k != "out":
                count += 1
                ax.add_patch(Rectangle((-side / 2 + i * s, -side / 2 + j * s), s, s,
                                       fc=SOLID if k == "in" else CUT, ec="white", lw=0.3,
                                       hatch=None if k == "in" else "////"))
    ax.add_patch(Circle((0.07, -0.05), 1.0, fill=False, ec=dg.INK, lw=0.8, ls="--"))
    ax.set_xlim(-1.3, 1.3)
    ax.set_ylim(-1.3, 1.3)
    ax.set_title(f"(a) uniform grid:\n{count} cells", fontsize=8)
    ax = fig.add_subplot(1, 3, 2)
    dg.bare(ax)
    for x0, y0, sz, k in leaves:
        ax.add_patch(Rectangle((x0, y0), sz, sz, fc=SOLID if k == "in" else CUT, ec="white",
                               lw=0.5, hatch=None if k == "in" else "////"))
    ax.add_patch(Circle((0.07, -0.05), 1.0, fill=False, ec=dg.INK, lw=0.8, ls="--"))
    ax.set_xlim(-1.3, 1.3)
    ax.set_ylim(-1.3, 1.3)
    ncut = sum(1 for lf in leaves if lf[3] == "cut")
    ax.set_title(f"(b) octree, same finest cell:\n{len(leaves)} leaves, {ncut} cut",
                 fontsize=8)
    ax = fig.add_subplot(1, 3, 3)
    view = lit.View(38, -58)
    depth = 4
    n3 = 2 ** depth
    h3 = 1.0 / n3
    _, _, _, lv = octree_counts(depth)
    low = [(o, sz, k) for o, sz, k in lv if o[2] + sz / 2 < 0.5]
    # the drawn leaves on the finest lattice: block id per finest cell (0 empty), and kind
    ids = np.zeros((n3, n3, n3), dtype=int)
    cells, kinds = [], []
    for b, (o, sz, k) in enumerate(low, start=1):
        i0 = np.rint(o / h3).astype(int)
        m = int(round(sz / h3))
        ids[i0[0]:i0[0] + m, i0[1]:i0[1] + m, i0[2]:i0[2] + m] = b
        g = np.stack(np.meshgrid(*[np.arange(i0[a], i0[a] + m) for a in range(3)], indexing="ij"),
                     -1).reshape(-1, 3)
        cells.append(g)
        kinds += [k] * len(g)
    ijk = np.concatenate(cells)

    def leaf(q: np.ndarray) -> np.ndarray:
        ok = np.all((q >= 0) & (q < n3), axis=1)
        out = np.zeros(len(q), dtype=int)
        out[ok] = ids[tuple(q[ok].T)]
        return out

    def solid(q: np.ndarray) -> np.ndarray:
        return leaf(q) > 0

    sc = lit.Scene(view)
    lit.add_voxels(sc, ijk, np.zeros(3), h3, solid, [SOLID if k == "in" else CUT for k in kinds],
                   [dg.BLUE if k == "in" else dg.VERMILION for k in kinds], 0.2, leaf=leaf)
    # the true surface: where the cut plane z = 0.5 meets the sphere, and the lower half of the
    # sphere's outline as seen from the eye
    c, r = np.array([0.503, 0.497, 0.501]), 0.39
    t = np.linspace(0, 2 * np.pi, 361)
    rr = math.sqrt(r * r - (0.5 - c[2]) ** 2)
    rim = c + np.column_stack([rr * np.cos(t), rr * np.sin(t), np.full_like(t, 0.5 - c[2])])
    e1 = view.right
    e2 = view.up
    sil = c + r * (np.cos(t)[:, None] * e1 + np.sin(t)[:, None] * e2)
    sil = sil[sil[:, 2] < 0.5]
    order = np.argsort(np.arctan2((sil - c) @ e2, (sil - c) @ e1) % (2 * np.pi))
    sil = sil[order]
    sc.wireframe([rim, sil], lit.occluded_by_cells(view, solid, np.zeros(3), h3, 1.5), 0.003)
    sc.draw(ax, np.array([[x, y, z] for x in (0.1, 0.9) for y in (0.1, 0.9) for z in (0.1, 0.52)]))
    ax.set_title("(c) octree in 3-D, lower half:\neight-way split", fontsize=8)
    fig.text(0.5, 0.0, "blue: interior, merged into the largest blocks that are wholly inside; "
             "orange, hatched: cut cells, always at the finest level; dashed: the true surface "
             "(in (c) the sphere's rim at the cut and its outline, grey where hidden)",
             ha="center", fontsize=6.8)
    fig.savefig(FIG / "diag-tree.pdf")
    plt.close(fig)


# ------------------------------------------------------------------ g

def fig_storage() -> None:
    depths = list(range(3, 9))
    rows = []
    for d in depths:
        u, nl, nc, _ = octree_counts(d)
        rows.append({"N": 2 ** d, "uniform": u, "leaves": nl, "cut": nc})
    DATA.mkdir(exist_ok=True)
    (DATA / "storage.json").write_text(json.dumps(rows, indent=1), encoding="utf-8")
    fig, ax = plt.subplots(figsize=(3.4, 2.6))
    ns = [r["N"] for r in rows]
    ax.loglog(ns, [r["uniform"] for r in rows], marker="o", color=dg.BLUE,
              label="uniform grid (cells in or cut), $\\propto N^3$")
    ax.loglog(ns, [r["leaves"] for r in rows], marker="s", color=dg.INK,
              label="octree leaves, $\\propto N^2$")
    ax.loglog(ns, [r["cut"] for r in rows], marker="^", color=dg.VERMILION, ls="--",
              label="cut cells, $\\propto N^2$")
    for r in rows:
        ax.annotate(f"{r['uniform'] / r['leaves']:.0f}$\\times$", (r["N"], r["leaves"]),
                    textcoords="offset points", xytext=(0, 6), ha="center", fontsize=6.5)
    ax.set_xlabel("finest cells across the root, $N$ (sphere: $0.78N$)")
    ax.set_ylabel("cells stored")
    ax.grid(True, color="#e0e0e0", lw=0.5)
    ax.legend(fontsize=6.3, frameon=False, loc="upper left")
    for sp in ("top", "right"):
        ax.spines[sp].set_visible(False)
    fig.savefig(FIG / "diag-storage.pdf")
    plt.close(fig)


# ------------------------------------------------------------------ h (and e)

def fig_read_cut() -> None:
    fig, (ax, bx) = plt.subplots(1, 2, figsize=(6.8, 3.4), gridspec_kw={"width_ratios": [1.15, 1]})
    dg.bare(ax)
    arm_x, top = 0.0, 10.1
    centre, radius = (2.45, 4.2), 2.15
    h = 0.25
    theta = 0.5  # accept a node when its side is at most theta times its distance

    def st(x0, y0, s):
        return state2(x0, y0, s, centre, radius)

    def dist(x0, y0, s):
        """Least distance from the node to the arm segment x = 0, 0 ≤ z ≤ top."""
        dx = max(x0 - arm_x, 0.0)
        dy = max(0.0, y0 - top, -(y0 + s))
        return math.hypot(dx, dy)

    counts = {"piece": 0, "moment": 0, "interior": 0, "node": 0}

    def visit(x0, y0, s):
        k = st(x0, y0, s)
        if k == "out":
            return
        d = dist(x0, y0, s)
        if s > h + 1e-12 and s > theta * d:
            for dx in (0, s / 2):
                for dy in (0, s / 2):
                    visit(x0 + dx, y0 + dy, s / 2)
            return
        if s <= h + 1e-12:
            if k == "cut" and d < 3 * h:
                counts["piece"] += 1
                ax.add_patch(Rectangle((x0, y0), s, s, fc=dg.ORANGE, ec=dg.VERMILION, lw=0.3,
                                       hatch="////"))
            elif k == "cut":
                counts["moment"] += 1
                ax.add_patch(Rectangle((x0, y0), s, s, fc=dg.GREEN, ec=dg.GREEN, lw=0.3,
                                       alpha=0.6))
            else:
                counts["interior"] += 1
                ax.add_patch(Rectangle((x0, y0), s, s, fc=dg.SKY, ec=dg.BLUE, lw=0.3))
        else:
            counts["node"] += 1
            ax.add_patch(Rectangle((x0, y0), s, s, fc="#dbe7f3", ec=dg.BLUE, lw=0.7, ls="--"))

    visit(0.2, 0.0, 8.0)
    ax.add_patch(Circle(centre, radius, fill=False, ec=dg.INK, lw=0.8, ls="--"))
    ax.plot([arm_x, arm_x], [0, top], color=dg.INK, lw=2.2)
    t = np.linspace(0, 1, 50)
    for z0 in (0.0, 5.0):
        ax.plot(arm_x - 0.15 * np.sin(np.pi * t), z0 + 4.4 * np.sin(np.pi * t) ** 0.7,
                color=dg.PURPLE, lw=0.9)
    ax.text(-0.3, top + 0.3, "tower and its arms", fontsize=7)
    ax.set_xlim(-0.6, 8.8)
    ax.set_ylim(-0.8, 11.0)
    ax.set_title("(a) the read's cut through the octree for one\ntower (a cross-section)", fontsize=8)
    # the layers, as bands of distance from the arm, with each one's error
    bx.set_xlim(0, 10)
    bx.set_ylim(0, 10)
    bx.axis("off")
    rows = [
        (dg.ORANGE, "////", "near: clipped pieces, closed form",
         "within $\\approx3$ cells of an arm; exact to the mesh;\nf64 rounding $\\approx10^{-11}$ rad",
         counts["piece"]),
        (dg.GREEN, None, "middle: cut-cell moments",
         "mass, centroid, second moment of each cut cell;\n$4\\times10^{-7}$ rad at 1.5 m, $h$ = 1/64 m (measured)",
         counts["moment"]),
        (dg.SKY, None, "interior cells at the finest level",
         "full cubes near the arm (the cube kernel)", counts["interior"]),
        ("#dbe7f3", None, "far: coarse nodes",
         "each node the sum of its leaves' moments, so the\ntrue body's; opened by a phase-error bound,\n$10^{-10}$ rad target",
         counts["node"]),
    ]
    for i, (fc, hatch, l1, l2, n) in enumerate(rows):
        y = 9.0 - 2.35 * i
        bx.add_patch(Rectangle((0.0, y - 0.35), 0.7, 0.7, fc=fc, ec=dg.INK2, lw=0.4, hatch=hatch,
                               alpha=0.6 if fc == dg.GREEN else 1.0))
        bx.text(1.0, y + 0.1, f"{l1} ({n} here)", fontsize=7, va="center")
        bx.text(1.0, y - 0.35, l2, fontsize=6.3, va="top", color=dg.INK2)
    bx.set_title("(b) the layers and their errors", fontsize=8)
    fig.savefig(FIG / "diag-read-cut.pdf")
    plt.close(fig)


def main() -> None:
    dg.style()
    FIG.mkdir(exist_ok=True)
    fig_tree()
    fig_storage()
    fig_read_cut()


if __name__ == "__main__":
    main()
